package io.github.jesterportfolio.hearth.survival;

import java.util.*;

/** 순정 생존의 월드 묶음. 경제/스토리 인벤토리·진행을 자동 이관하지 않습니다. */
public record SurvivalSettings(UUID group,boolean allowCreate,Map<SurvivalWorld,Definition> worlds) {
    public record Definition(String key,String environment,String terrain,Long seed){public Definition{if(key==null||!key.matches("[a-z0-9_]+:[a-z0-9_]+")||!Set.of("NORMAL","NETHER").contains(environment)||!Set.of("NORMAL","FLAT").contains(terrain)||environment.equals("NETHER")&&!terrain.equals("NORMAL"))throw new IllegalArgumentException("SURVIVAL_WORLD_CONFIG");}}
    public SurvivalSettings{Objects.requireNonNull(group);worlds=Map.copyOf(worlds);if(!worlds.keySet().equals(EnumSet.allOf(SurvivalWorld.class))||worlds.values().stream().map(Definition::key).distinct().count()!=3||!worlds.get(SurvivalWorld.RESIDENCE).environment().equals("NORMAL")||!worlds.get(SurvivalWorld.WILDERNESS).environment().equals("NORMAL")||!worlds.get(SurvivalWorld.NETHER).environment().equals("NETHER"))throw new IllegalArgumentException("SURVIVAL_WORLD_CONFIG");}
    public static SurvivalSettings parse(Map<String,?> values){var definitions=new EnumMap<SurvivalWorld,Definition>(SurvivalWorld.class);Object raw=values.get("worlds");if(!(raw instanceof Map<?,?> root))throw new IllegalArgumentException("SURVIVAL_WORLD_CONFIG");for(var role:SurvivalWorld.values()){if(!(root.get(role.id()) instanceof Map<?,?> row)||!(row.get("key") instanceof String key))throw new IllegalArgumentException("SURVIVAL_WORLD_CONFIG");String environment=role==SurvivalWorld.NETHER?"NETHER":"NORMAL";Object rawTerrain=row.get("terrain"),rawSeed=row.get("seed");String terrain=rawTerrain==null?"NORMAL":String.valueOf(rawTerrain);Long seed=null;if(rawSeed!=null){if(!(rawSeed instanceof Byte||rawSeed instanceof Short||rawSeed instanceof Integer||rawSeed instanceof Long))throw new IllegalArgumentException("SURVIVAL_SEED");seed=((Number)rawSeed).longValue();}definitions.put(role,new Definition(key,environment,terrain,seed));}if(!(values.get("group-id") instanceof String group)||!(values.get("allow-create") instanceof Boolean create))throw new IllegalArgumentException("SURVIVAL_CONFIG");return new SurvivalSettings(UUID.fromString(group),create,definitions);}
}
